import { createAdminImport, getAdminImport, editAdminImport, listAdminImports, analyzeAdminImport, cancelAdminImportAnalysis, adoptAdminImportSuggestions, adminImportDuplicateCandidates, decideAdminImportDuplicates, initializeAdminImportStorage, runAdminImportWorkerOnce } from '../../src/administration/import/adminImportService';

let harness: MongoReplicaSetHarness; const actor = new ObjectId(), other = new ObjectId(), ordinary = new ObjectId();
const make = () => ({ operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Artist - Album', files: [{ slotId: randomUUID(), filename: '01 - Song.mp3', relativePath: 'Disc 1/01 - Song.mp3', byteLength: 123 }] } });
const create = () => createAdminImport(actor.toHexString(), make());
const mutation = (revision: number) => ({ operationId: randomUUID(), expectedRevision: revision });
const provider: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album ? [{ scope: 'album', slotId: null, field: 'title', baseline: input.baseline.album.title, value: 'Album', source: 'folder', evidence: input.manifest.rootLabel }] : [] };
const errorCode = (code: string) => (error: unknown) => error instanceof AdminImportError && error.code === code;
const deferred = () => { let resolve!: () => void; const promise = new Promise<void>(r => { resolve = r; }); return { promise, resolve }; };
before(async () => { harness = await startMongoReplicaSet('archtree-admin-import-test'); });
beforeEach(async () => {
    process.env.FINITUDE_ADMIN_IMPORTS_ENABLED = 'true'; const db = getDb()!;
    for (const name of ['users', 'adminAlbumImports', 'adminImportAnalysisSlots', 'artists', 'albums', 'audioTracks']) await db.collection(name).deleteMany({});
    await db.collection('users').insertMany([{ _id: actor, email: 'admin-import@example.test', role: 'admin' }, { _id: other, email: 'other-import@example.test', role: 'admin' }, { _id: ordinary, email: 'ordinary-import@example.test', role: 'user' }]); await initializeAdminImportStorage(db);
});
after(async () => { delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED; await harness?.stop(); });

test('create retries are durable across flag rollback, mismatched intent rejected, and admin inventory is shared', async () => {
    const body = make(); const [a, b] = await Promise.all([createAdminImport(actor.toHexString(), body), createAdminImport(actor.toHexString(), body)]); assert.equal(a.item.id, b.item.id);
    delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED;
    assert.equal((await createAdminImport(actor.toHexString(), body)).receipt!.revision, 1);
    await assert.rejects(create(), errorCode('ADMIN_IMPORTS_DISABLED'));
    await assert.rejects(createAdminImport(actor.toHexString(), { ...body, manifest: { ...body.manifest, rootLabel: 'different' } }), errorCode('ADMIN_IMPORT_OPERATION_CONFLICT'));
    assert.equal((await getAdminImport(other.toHexString(), a.item.id)).item.startedByMe, false);
    await assert.rejects(getAdminImport(ordinary.toHexString(), a.item.id), errorCode('ADMIN_IMPORT_ADMIN_REQUIRED'));
    assert.equal(await getDb()!.collection('adminAlbumImports').countDocuments(), 1);
});
test('manual draft revision races have one winner and replay survives later edits', async () => {
    const first = await create(), draft = first.item.draft; draft.album.title = 'First'; const body = { ...mutation(1), draft };
    const results = await Promise.allSettled([editAdminImport(actor.toHexString(), first.item.id, body), editAdminImport(other.toHexString(), first.item.id, { ...mutation(1), draft: { ...draft, album: { ...draft.album, title: 'Other' } } })]);
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 1); assert.equal(results.filter(r => r.status === 'rejected').length, 1);
    const current = await getAdminImport(actor.toHexString(), first.item.id); assert.equal(current.item.revision, 2);
    const winning = results[0].status === 'fulfilled'; if (winning) assert.equal((await editAdminImport(actor.toHexString(), first.item.id, body)).receipt!.revision, 2);
});
test('inventory uses stable pagination and full counts; no reads enqueue work or expose actor identifiers', async () => {
    for (let i = 0; i < 3; i++) await create();
    const page = await listAdminImports(other.toHexString(), { limit: '2' }); assert.equal(page.items.length, 2); assert.equal(page.counts.all, 3); assert.equal(page.counts.awaitingReview, 3); assert.equal(page.counts.completed, 0);
    const second = await listAdminImports(other.toHexString(), { limit: '2', cursor: page.nextCursor! }); assert.equal(second.items.length, 1); assert.equal(new Set([...page.items, ...second.items].map(i => i.id)).size, 3);
    assert.equal((await listAdminImports(other.toHexString(), { startedByMe: 'true' })).counts.all, 0);
    assert.equal(JSON.stringify(page).includes(actor.toHexString()), false); assert.equal(page.items.every(i => i.analysis.state === 'idle' && i.upload.ready === 0 && i.publication === 'notStarted'), true);
    await assert.rejects(listAdminImports(other.toHexString(), { q: 'new', cursor: page.nextCursor! }), errorCode('ADMIN_IMPORT_INVALID_INPUT'));
});
test('analysis admission is durable/idempotent and one active job per actor across concurrent requests', async () => {
    const a = await create(), b = await create(), body = mutation(1);
    const results = await Promise.allSettled([analyzeAdminImport(actor.toHexString(), a.item.id, body, provider), analyzeAdminImport(actor.toHexString(), b.item.id, mutation(1), provider)]);
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 1);
    const winning = results.find(r => r.status === 'fulfilled') as PromiseFulfilledResult<any>; assert.equal(winning.value.item.analysis.state, 'queued'); assert.equal(winning.value.item.analysis.attemptsUsed, 0);
    if (results[0].status === 'fulfilled') assert.equal((await analyzeAdminImport(actor.toHexString(), a.item.id, body, provider)).item.analysis.generation, 1);
    const stored = await getDb()!.collection('adminAlbumImports').findOne({ _id: new ObjectId(winning.value.item.id) }); assert.equal(stored!.analysis.actorId, actor.toHexString()); assert.equal(stored!.analysis.chunks.length, 2); assert.equal(stored!.analysis.grantExpiresAt instanceof Date, true);
});
test('cancelled in-flight analysis retains actor and global capacity until its provider outcome is checkpointed', async () => {
    const first = await create(), next = await create();
    await analyzeAdminImport(actor.toHexString(), first.item.id, mutation(1), provider);
    const entered = deferred(), release = deferred();
    const worker = runAdminImportWorkerOnce({ configured: () => true, analyze: async () => { entered.resolve(); await release.promise; return []; } });
    await entered.promise;
    try {
        const current = await getAdminImport(actor.toHexString(), first.item.id);
        await cancelAdminImportAnalysis(actor.toHexString(), first.item.id, mutation(current.item.revision));
        await assert.rejects(analyzeAdminImport(actor.toHexString(), next.item.id, mutation(1), provider), errorCode('ADMIN_IMPORT_ACTOR_BUSY'));
        const second = await createAdminImport(other.toHexString(), make());
        await analyzeAdminImport(other.toHexString(), second.item.id, mutation(1), provider);
        await getDb()!.collection('users').updateOne({ _id: ordinary }, { $set: { role: 'admin' } });
        const third = await createAdminImport(ordinary.toHexString(), make());
        await assert.rejects(analyzeAdminImport(ordinary.toHexString(), third.item.id, mutation(1), provider), errorCode('ADMIN_IMPORT_CAPACITY'));
    } finally { release.resolve(); await worker; }
    assert.equal((await analyzeAdminImport(actor.toHexString(), next.item.id, mutation(1), provider)).item.analysis.state, 'queued');
});
test('server checkpoint survives independent worker ticks and never overwrites manual edits', async () => {
    const first = await create(); await analyzeAdminImport(actor.toHexString(), first.item.id, mutation(1), provider);
    const entered = deferred(), release = deferred(); let calls = 0;
    const waiting: ImportAnalysisProvider = { configured: () => true, analyze: async input => { calls++; entered.resolve(); await release.promise; return provider.analyze(input); } };
    const worker = runAdminImportWorkerOnce(waiting); await entered.promise;
    const current = await getAdminImport(actor.toHexString(), first.item.id); current.item.draft.album.artistName = 'Manually selected'; await editAdminImport(actor.toHexString(), first.item.id, { ...mutation(current.item.revision), draft: current.item.draft });
    release.resolve(); await worker; await runAdminImportWorkerOnce(provider);
    const done = await getAdminImport(actor.toHexString(), first.item.id); assert.equal(done.item.analysis.state, 'complete'); assert.equal(done.item.analysis.completedChunks, 2); assert.equal(done.item.analysis.attemptsUsed, 2); assert.equal(done.item.draft.album.artistName, 'Manually selected'); assert.equal(done.item.draft.album.title, ''); assert.equal(done.item.suggestions[0].value, 'Album'); assert.equal(calls, 1);
    assert.equal(await runAdminImportWorkerOnce(waiting), false); assert.equal(calls, 1);
});
test('daily deployment budget serializes competing workers and never dispatches the losing reservation', async () => {
    const a = await create(), b = await createAdminImport(other.toHexString(), make()), now = new Date();
    await analyzeAdminImport(actor.toHexString(), a.item.id, mutation(1), provider);
    await analyzeAdminImport(other.toHexString(), b.item.id, mutation(1), provider);
    const _id = `daily:${now.toISOString().slice(0, 10)}`;
    await getDb()!.collection<{ _id: string; attempts: number }>('adminImportAnalysisSlots').insertOne({ _id, attempts: ADMIN_IMPORT_LIMITS.dailyAttempts - 1 });
    let calls = 0;
    const counted: ImportAnalysisProvider = { configured: () => true, analyze: async () => { calls++; return []; } };
    await Promise.all([runAdminImportWorkerOnce(counted, now), runAdminImportWorkerOnce(counted, now)]);
    assert.equal(calls, 1);
    assert.equal((await getDb()!.collection<{ _id: string; attempts: number }>('adminImportAnalysisSlots').findOne({ _id }))!.attempts, ADMIN_IMPORT_LIMITS.dailyAttempts);
    const items = [(await getAdminImport(actor.toHexString(), a.item.id)).item, (await getAdminImport(other.toHexString(), b.item.id)).item];
    assert.equal(items.filter(item => item.analysis.issue === 'budgetExhausted').length, 1);
    await runAdminImportWorkerOnce(counted, now); assert.equal(calls, 1);
});
test('uncertain provider outcomes consume the daily reservation and a new UTC day receives its own budget', async () => {
    const first = await create(), now = new Date();
    await analyzeAdminImport(actor.toHexString(), first.item.id, mutation(1), provider);
    const _id = `daily:${now.toISOString().slice(0, 10)}`;
    await runAdminImportWorkerOnce({ configured: () => true, analyze: async () => { throw new ImportProviderError('providerOutcomeUnknown'); } }, now);
    assert.equal((await getDb()!.collection<{ _id: string; attempts: number }>('adminImportAnalysisSlots').findOne({ _id }))!.attempts, 1);
    await getDb()!.collection<{ _id: string; attempts: number }>('adminImportAnalysisSlots').updateOne({ _id }, { $set: { attempts: ADMIN_IMPORT_LIMITS.dailyAttempts } });
    const second = await create(); await analyzeAdminImport(actor.toHexString(), second.item.id, mutation(1), provider);
    const tomorrow = new Date(now.getTime() + 86_400_000);
    await getDb()!.collection('adminAlbumImports').updateOne({ _id: new ObjectId(second.item.id) }, { $set: { 'analysis.grantExpiresAt': new Date(tomorrow.getTime() + 60_000) } });
    await runAdminImportWorkerOnce(provider, tomorrow);
    assert.equal((await getDb()!.collection<{ _id: string; attempts: number }>('adminImportAnalysisSlots').findOne({ _id: `daily:${tomorrow.toISOString().slice(0, 10)}` }))!.attempts, 1);
    assert.equal((await getAdminImport(actor.toHexString(), second.item.id)).item.analysis.attemptsUsed, 1);
});
