test('duplicate candidates include hidden ready identities without raw storage and prevent cross-album track reuse', async () => {
    const first = await create(), artistId = new ObjectId(), albumId = new ObjectId(), trackId = new ObjectId(), broken = new ObjectId();
    const draft = first.item.draft; draft.album.artistName = 'Same name'; draft.album.title = 'Edition'; draft.tracks[0].title = 'Recording'; await editAdminImport(actor.toHexString(), first.item.id, { ...mutation(1), draft });
    await getDb()!.collection('artists').insertMany([{ _id: artistId, name: 'Same name', visibility: 'hidden', lifecycleStatus: 'ready' }, { _id: broken, name: 'Same name', lifecycleStatus: 'deleteFailed' }]);
    await getDb()!.collection('albums').insertOne({ _id: albumId, title: 'Edition', lifecycleStatus: 'ready' });
    await getDb()!.collection('audioTracks').insertOne({ _id: trackId, title: 'Recording', albumId: albumId.toHexString(), s3Key: trackId.toHexString(), uploadStatus: 'ready', publicationStatus: 'ready' });
    const { items } = await adminImportDuplicateCandidates(actor.toHexString(), first.item.id); assert.equal(items.length, 3); assert.equal(items[0].visibility, 'hidden'); assert.equal(JSON.stringify(items).includes('s3Key'), false);
    const track = items.find(i => i.kind === 'track')!, album = items.find(i => i.kind === 'album')!;
    const decision = { scope: 'track', slotId: draft.tracks[0].slotId, action: 'reuse', candidateId: track.id, candidateRevision: track.revision };
    await assert.rejects(decideAdminImportDuplicates(actor.toHexString(), first.item.id, { ...mutation(2), decisions: [decision] }), errorCode('ADMIN_IMPORT_TRACK_BELONGS_TO_ALBUM'));
    const result = await decideAdminImportDuplicates(actor.toHexString(), first.item.id, { ...mutation(2), decisions: [decision, { scope: 'album', slotId: null, action: 'reuse', candidateId: album.id, candidateRevision: album.revision }] }); assert.equal(result.item.decisions.length, 2);
    await getDb()!.collection('audioTracks').updateOne({ _id: trackId }, { $set: { title: 'Changed' } });
    await assert.rejects(decideAdminImportDuplicates(actor.toHexString(), first.item.id, { ...mutation(result.item.revision), decisions: result.item.decisions }), errorCode('ADMIN_IMPORT_DUPLICATE_STALE'));
});

test('analysis checkpoints retain admitted tag context despite later upload metadata changes', async () => {
    const first = await create(), slotId = first.item.manifest.files[0].slotId;
    const tags = { title: 'Original tag', album: 'Embedded album', artists: ['Embedded artist'], year: 2020, trackNumber: 9 };
    await getDb()!.collection('adminAlbumImports').updateOne({ _id: new ObjectId(first.item.id) }, { $set: { 'media.assets': [{ slotId, state: 'ready', tags, recovery: { operationId: randomUUID(), expectedRevision: 1, kind: 'upload', actorId: actor.toHexString() } }] } });
    await analyzeAdminImport(actor.toHexString(), first.item.id, mutation(1), provider);
    await getDb()!.collection('adminAlbumImports').updateOne({ _id: new ObjectId(first.item.id) }, { $set: { 'media.assets.0.tags.title': 'Changed after enqueue' } });
    let seen = 0; const observing: ImportAnalysisProvider = { configured: () => true, analyze: async input => { assert.deepEqual(input.tags, [{ slotId, tags }]); assert.equal(input.manifest.rootLabel, first.item.manifest.rootLabel); seen++; return []; } };
    await runAdminImportWorkerOnce(observing); await runAdminImportWorkerOnce(observing); assert.equal(seen, 2); assert.equal((await getAdminImport(actor.toHexString(), first.item.id)).item.draft.tracks[0].title, '');
});
